-- ======================================================================
-- MIGRATION · 008_create_sovereignty_tables.sql
-- ======================================================================

-- Migration 008: Sovereign Cyber-Risk Observatory governance schema
-- Creates the gov schema, adds governance dimensions to asset.assets,
-- and establishes the third-party risk (TPRM) tables.

-- ─── gov schema ───────────────────────────────────────────────
CREATE SCHEMA IF NOT EXISTS gov;

-- Agencies / public organs / enterprises under observation
CREATE TABLE IF NOT EXISTS gov.agencies (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name             VARCHAR(255) NOT NULL UNIQUE,
    agency_type      VARCHAR(30) NOT NULL DEFAULT 'PUBLIC',
                     -- PUBLIC, REGULATOR, GOVT, PSU, PRIVATE
    sector           VARCHAR(50),
    region           VARCHAR(50),
    parent_agency_id UUID REFERENCES gov.agencies(id),
    classification   VARCHAR(20) DEFAULT 'CONFIDENTIAL',
    created_at       TIMESTAMP DEFAULT NOW()
);

-- Sector profiles: regulator ownership + SRI weight + thresholds
CREATE TABLE IF NOT EXISTS gov.sector_profiles (
    sector                 VARCHAR(50) PRIMARY KEY,
    sector_name            VARCHAR(255) NOT NULL,
    regulator              VARCHAR(255),
    threshold_critical_mln DECIMAL(12,2) DEFAULT 0,
    weight                 NUMERIC(5,4) DEFAULT 1.0,
    created_at             TIMESTAMP DEFAULT NOW()
);

-- National cyber exercises / drills (history)
CREATE TABLE IF NOT EXISTS gov.exercises (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name                  VARCHAR(255) NOT NULL,
    scenario_key          VARCHAR(100) NOT NULL,
                          -- WORM, RANSOMWARE, SUPPLY_CHAIN, DDOS
    impact_scope          VARCHAR(30) NOT NULL DEFAULT 'NATIONAL',
                          -- SECTOR, REGION, AGENCY, NATIONAL
    sector                VARCHAR(50),
    region                VARCHAR(50),
    baseline_eal          DECIMAL(15,2),
    simulated_eal         DECIMAL(15,2),
    eal_reduction         DECIMAL(15,2),
    eal_reduction_percent DECIMAL(6,2),
    status                VARCHAR(20) DEFAULT 'COMPLETED',
                          -- COMPLETED, RUNNING, SCHEDULED
    executed_by           UUID,
    executed_at           TIMESTAMP DEFAULT NOW()
);

-- Early warnings / escalations
CREATE TABLE IF NOT EXISTS gov.early_warnings (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    warning_type    VARCHAR(50) NOT NULL,
                    -- EAL_SPIKE, SECTOR_CRITICAL, VULN_BREACH, VENDOR_RISK
    target_type     VARCHAR(30) NOT NULL,
                    -- SECTOR, REGION, AGENCY, ASSET, VENDOR
    target_id       VARCHAR(100),
    severity        VARCHAR(10) NOT NULL,
                    -- CRITICAL, HIGH, MEDIUM, LOW
    title           VARCHAR(500),
    description     TEXT,
    threshold_value DECIMAL(15,2),
    current_value   DECIMAL(15,2),
    status          VARCHAR(20) DEFAULT 'OPEN',
                    -- OPEN, ESCALATED, RESOLVED
    created_at      TIMESTAMP DEFAULT NOW()
);

-- Third-party vendors / service providers
CREATE TABLE IF NOT EXISTS gov.vendors (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name              VARCHAR(255) NOT NULL UNIQUE,
    vendor_type       VARCHAR(50),
                      -- MSP, SAAS, HARDWARE, INTEGRATOR, CLOUD
    criticality_score INTEGER DEFAULT 50,
    business_value_inr DECIMAL(15,2) DEFAULT 0,
    sector            VARCHAR(50),
    region            VARCHAR(50),
    assessment_score  DECIMAL(5,4) DEFAULT 0,
                      -- 0.0000 to 1.0000 (third-party assessment)
    last_assessed_at  TIMESTAMP,
    created_at        TIMESTAMP DEFAULT NOW()
);

-- Vendor → asset service map (TPRM cascade edges)
CREATE TABLE IF NOT EXISTS gov.asset_vendors (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    asset_id     UUID NOT NULL REFERENCES asset.assets(id) ON DELETE CASCADE,
    vendor_id    UUID NOT NULL REFERENCES gov.vendors(id) ON DELETE CASCADE,
    service_type VARCHAR(50),
    risk_share   DECIMAL(5,4) DEFAULT 1.0,
                 -- portion of asset risk attributable to this vendor
    created_at   TIMESTAMP DEFAULT NOW(),
    UNIQUE(asset_id, vendor_id)
);

-- ─── Governance dimensions on assets ─────────────────────────
ALTER TABLE asset.assets ADD COLUMN IF NOT EXISTS sector VARCHAR(50);
ALTER TABLE asset.assets ADD COLUMN IF NOT EXISTS region VARCHAR(50);
ALTER TABLE asset.assets ADD COLUMN IF NOT EXISTS agency_id UUID;
ALTER TABLE asset.assets ADD COLUMN IF NOT EXISTS is_critical_infra BOOLEAN DEFAULT false;
ALTER TABLE asset.assets ADD COLUMN IF NOT EXISTS classification VARCHAR(20) DEFAULT 'CONFIDENTIAL';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_assets_sector_region ON asset.assets(sector, region);
CREATE INDEX IF NOT EXISTS idx_assets_agency ON asset.assets(agency_id);
CREATE INDEX IF NOT EXISTS idx_assets_critical_infra ON asset.assets(is_critical_infra)
    WHERE is_critical_infra = true;

CREATE INDEX IF NOT EXISTS idx_vendors_sector ON gov.vendors(sector);
CREATE INDEX IF NOT EXISTS idx_asset_vendors_vendor ON gov.asset_vendors(vendor_id);
CREATE INDEX IF NOT EXISTS idx_exercises_sector ON gov.exercises(sector);
CREATE INDEX IF NOT EXISTS idx_warnings_type ON gov.early_warnings(warning_type);


-- ======================================================================
-- MIGRATION · 009_create_data_sources.sql
-- ======================================================================

-- Migration 009: Registered ingestion data sources
-- Tracks the 7 production connectors feeding the observatory (scanners,
-- EDR, SIEM, web-edge logs, file-based batches) plus their health state.

CREATE TABLE IF NOT EXISTS public.data_sources (
    source_key        VARCHAR(50) PRIMARY KEY,
    name              VARCHAR(255) NOT NULL,
    connector_type    VARCHAR(50) NOT NULL,
                      -- SCANNER, EDR, SIEM, WEB, FILE
    status            VARCHAR(20) NOT NULL DEFAULT 'CONFIGURED',
                      -- CONFIGURED, ACTIVE, CONNECTED, STANDBY, FAILED
    description       TEXT,
    last_ingested_at  TIMESTAMP,
    records_ingested  INTEGER DEFAULT 0,
    error_count       INTEGER DEFAULT 0,
    created_at        TIMESTAMP DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_data_sources_status ON public.data_sources(status);


-- ======================================================================
-- MIGRATION · 010_create_python_features.sql
-- ======================================================================

-- Migration 010: Refresh-token rotation, normalized event ledger, and the
-- RAG compliance corpus (pgvector embeddings stored as JSONB for portability).

-- ─── Refresh-token rotation ledger ───────────────────────────
CREATE TABLE IF NOT EXISTS auth.refresh_tokens (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    token_hash  VARCHAR(128) NOT NULL UNIQUE,
    family_id   UUID NOT NULL DEFAULT gen_random_uuid(),
    created_at  TIMESTAMP NOT NULL DEFAULT NOW(),
    expires_at  TIMESTAMP NOT NULL,
    revoked_at  TIMESTAMP,
    replaced_by UUID
);

CREATE INDEX IF NOT EXISTS idx_refresh_tokens_user ON auth.refresh_tokens(user_id);
CREATE INDEX IF NOT EXISTS idx_refresh_tokens_family ON auth.refresh_tokens(family_id);
CREATE INDEX IF NOT EXISTS idx_refresh_tokens_revoked ON auth.refresh_tokens(revoked_at)
    WHERE revoked_at IS NULL;

-- ─── Normalized ingestion event ledger ───────────────────────
CREATE TABLE IF NOT EXISTS public.security_events (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    event_type   VARCHAR(50) NOT NULL,
    source_asset UUID,
    source       VARCHAR(50) NOT NULL,
    details      TEXT,
    timestamp    TIMESTAMP NOT NULL DEFAULT NOW(),
    processed    BOOLEAN NOT NULL DEFAULT false,
    created_at   TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_security_events_type ON public.security_events(event_type);
CREATE INDEX IF NOT EXISTS idx_security_events_asset ON public.security_events(source_asset);
CREATE INDEX IF NOT EXISTS idx_security_events_ts ON public.security_events(timestamp DESC);

-- ─── RAG compliance corpus ───────────────────────────────────
-- embeddings are stored as JSONB for portability; try to enable pgvector
-- where available but never let its absence abort the migration.
DO $$
BEGIN
    CREATE EXTENSION IF NOT EXISTS vector;
EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'pgvector extension unavailable; embeddings retained as JSONB';
END $$;

CREATE TABLE IF NOT EXISTS gov.compliance_docs (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    framework   VARCHAR(50) NOT NULL,
    category    VARCHAR(100),
    title       VARCHAR(255) NOT NULL,
    content     TEXT NOT NULL,
    reference   VARCHAR(255),
    embedding   JSONB,
    created_at  TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_compliance_docs_framework ON gov.compliance_docs(framework);


-- ======================================================================
-- MIGRATION · 011_create_threat_intel.sql
-- ======================================================================

-- Threat-intel feed snapshot cache (WS4).
-- Enrichment records pulled from CISA KEV, FIRST EPSS and NVD.
-- Kept in Postgres so the platform degrades gracefully offline.
CREATE TABLE IF NOT EXISTS public.threat_intel (
    id          SERIAL PRIMARY KEY,
    feed        VARCHAR(32) NOT NULL,
    cve_id      VARCHAR(32) NOT NULL,
    source_key  VARCHAR(64),
    payload     JSONB,
    fetched_at  TIMESTAMP   DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_threat_intel_feed_cve ON public.threat_intel (feed, cve_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_threat_intel_feed_cve ON public.threat_intel (feed, cve_id);


-- ======================================================================
-- MIGRATION · 012_create_alert_system.sql
-- ======================================================================

-- Alert rule engine + alert event ledger (WS8).
-- Threshold rules evaluated against risk metrics; fired alerts are persisted
-- and broadcast on the /topic/risk/alert STOMP topic for the live feed.
CREATE TABLE IF NOT EXISTS public.alert_rules (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name            VARCHAR(120) NOT NULL,
    metric          VARCHAR(32)  NOT NULL,   -- risk_score | total_eal | open_vulns | kev_count
    operator        VARCHAR(4)   DEFAULT '>=',
    threshold       NUMERIC(14, 2) NOT NULL,
    asset_id        UUID,
    severity        VARCHAR(16)  DEFAULT 'HIGH',  -- INFO | LOW | MEDIUM | HIGH | CRITICAL
    enabled         BOOLEAN      DEFAULT TRUE,
    created_at      TIMESTAMP    DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.alert_events (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    rule_id     UUID REFERENCES public.alert_rules(id) ON DELETE SET NULL,
    metric      VARCHAR(32) NOT NULL,
    observed    NUMERIC(14, 2) NOT NULL,
    threshold   NUMERIC(14, 2) NOT NULL,
    severity    VARCHAR(16) NOT NULL,
    asset_id    UUID,
    payload     JSONB,
    fired_at    TIMESTAMP DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_alert_events_fired ON public.alert_events (fired_at DESC);
CREATE INDEX IF NOT EXISTS idx_alert_rules_enabled ON public.alert_rules (enabled);

