INSERT INTO vuln.vulnerabilities (
    cve_id, cwe_id, title, description, cvss_score, severity,
    exploitability, affected_asset, internet_exposed, status, remediation, source
) VALUES
    ('CVE-2026-1001','CWE-89','SQL Injection in Payment API Endpoint','A critical SQL injection vulnerability was discovered in the payment processing API, allowing unauthenticated attackers to execute arbitrary SQL queries.',9.8,'CRITICAL',9.5,'00000001-0001-0001-0001-000000000001',TRUE,'OPEN','Apply parameterized queries to all database interactions. Deploy WAF rules as interim mitigation.','SCANNER'),
    ('CVE-2026-1002','CWE-798','Hardcoded Credentials in Cloud Management CLI','The cloud management CLI tool contains hardcoded AWS access keys in the source code repository.',9.1,'CRITICAL',9.0,'00000001-0001-0001-0001-000000000008',TRUE,'OPEN','Rotate all exposed credentials immediately. Implement secrets management (AWS Secrets Manager).','PENTEST'),
    ('CVE-2026-1003','CWE-22','Path Traversal in Customer Portal File Upload','The customer web portal allows arbitrary file read through path traversal in the file upload handler.',8.6,'CRITICAL',8.5,'00000001-0001-0001-0001-000000000004',TRUE,'OPEN','Sanitize file paths. Implement allowlist-based file access controls.','SCANNER'),
    ('CVE-2026-1004','CWE-611','XML External Entity (XXE) in API Gateway','The API gateway parses untrusted XML input without disabling external entity resolution.',8.2,'CRITICAL',8.0,'00000001-0001-0001-0001-000000000005',TRUE,'OPEN','Disable DTD processing and external entity resolution in XML parser.','SCANNER'),
    ('CVE-2026-1005','CWE-502','Deserialization of Untrusted Data in SIEM Collector','The SIEM log collector deserializes data from network sources without validation.',8.0,'CRITICAL',7.5,'00000001-0001-0001-0001-000000000009',FALSE,'OPEN','Implement input validation and use safe serialization libraries.','SCANNER'),
    ('CVE-2026-1006','CWE-287','Missing MFA on Identity Provider Admin Console','The IdP administrative console does not enforce multi-factor authentication for administrative users.',7.8,'HIGH',7.5,'00000001-0001-0001-0001-000000000003',TRUE,'OPEN','Enable mandatory MFA for all administrative accounts.','MANUAL'),
    ('CVE-2026-1007','CWE-311','Missing Encryption on Database Backups','Customer database backups are stored without encryption at rest.',7.5,'HIGH',6.0,'00000001-0001-0001-0001-000000000007',FALSE,'OPEN','Enable AES-256 encryption for all backup volumes.','MANUAL'),
    ('CVE-2026-1008','CWE-326','Weak TLS Configuration on VPN','VPN concentrator accepts TLS 1.0 and 1.1 connections, which are deprecated.',7.2,'HIGH',7.0,'00000001-0001-0001-0001-000000000012',TRUE,'OPEN','Disable TLS 1.0/1.1. Enforce TLS 1.3 minimum.','SCANNER'),
    ('CVE-2026-1009','CWE-918','Server-Side Request Forgery in Analytics Dashboard','The analytics dashboard fetches external URLs without validation, enabling SSRF attacks.',7.0,'HIGH',6.5,'00000001-0001-0001-0001-000000000011',FALSE,'OPEN','Implement URL allowlisting and block internal IP ranges.','SCANNER'),
    ('CVE-2026-1010','CWE-269','Privilege Escalation via Email Server','Regular users can access admin endpoints on the email server due to missing authorization checks.',6.8,'HIGH',6.0,'00000001-0001-0001-0001-000000000006',TRUE,'IN_PROGRESS','Implement role-based access control on all admin endpoints.','PENTEST'),
    ('CVE-2026-1011','CWE-770','Unrestricted File Upload in Customer Portal','No file type or size restrictions on customer portal upload feature.',6.5,'HIGH',6.0,'00000001-0001-0001-0001-000000000004',TRUE,'OPEN','Implement file type validation, size limits, and virus scanning.','SCANNER'),
    ('CVE-2026-1012','CWE-330','Insufficient Entropy in Session Tokens','Session tokens are generated using a predictable PRNG.',6.2,'MEDIUM',5.5,'00000001-0001-0001-0001-000000000004',TRUE,'OPEN','Use cryptographically secure random number generator for session tokens.','SCANNER'),
    ('CVE-2026-1013','CWE-532','Sensitive Information in Log Files','Payment processing logs contain PII and card data in plaintext.',5.5,'MEDIUM',4.0,'00000001-0001-0001-0001-000000000001',FALSE,'IN_PROGRESS','Implement log scrubbing to remove PII. Use structured logging with redaction.','SCANNER'),
    ('CVE-2026-1014','CWE-200','Information Disclosure via Error Messages','Verbose error messages expose internal stack traces and configuration details.',5.3,'MEDIUM',5.0,'00000001-0001-0001-0001-000000000005',TRUE,'OPEN','Implement generic error responses in production mode.','SCANNER'),
    ('CVE-2026-1015','CWE-759','No Salt in Password Hashing','Legacy authentication module uses MD5 without salt for password hashing.',5.0,'MEDIUM',4.5,'00000001-0001-0001-0001-000000000003',FALSE,'OPEN','Migrate to bcrypt/Argon2 with per-user salts.','MANUAL');

