SELECT 'auth.users' AS table_name, COUNT(*) AS rows FROM auth.users
UNION ALL SELECT 'asset.assets', COUNT(*) FROM asset.assets
UNION ALL SELECT 'control.security_controls', COUNT(*) FROM control.security_controls
UNION ALL SELECT 'vuln.vulnerabilities', COUNT(*) FROM vuln.vulnerabilities
UNION ALL SELECT 'control.asset_controls', COUNT(*) FROM control.asset_controls
UNION ALL SELECT 'asset.asset_dependencies', COUNT(*) FROM asset.asset_dependencies
UNION ALL SELECT 'risk.risk_calculations', COUNT(*) FROM risk.risk_calculations
UNION ALL SELECT 'risk.risk_snapshots', COUNT(*) FROM risk.risk_snapshots
UNION ALL SELECT 'gov.agencies', COUNT(*) FROM gov.agencies
UNION ALL SELECT 'gov.sector_profiles', COUNT(*) FROM gov.sector_profiles
UNION ALL SELECT 'gov.vendors', COUNT(*) FROM gov.vendors
UNION ALL SELECT 'gov.asset_vendors', COUNT(*) FROM gov.asset_vendors
UNION ALL SELECT 'gov.exercises', COUNT(*) FROM gov.exercises
UNION ALL SELECT 'gov.early_warnings', COUNT(*) FROM gov.early_warnings
UNION ALL SELECT 'public.data_sources', COUNT(*) FROM public.data_sources
UNION ALL SELECT 'public.alert_rules', COUNT(*) FROM public.alert_rules
ORDER BY table_name;
